def check_dual_parser(ok, sample_n=None):
    """🆕 2026-10-14（诊断 P2-9）：断言两套 frontmatter 解析器结果等价。

    本库有**两套**解析器：`kb_lib.parse_frontmatter`（自研轻量，写入/索引侧）
    与 `yaml.safe_load`（lint 侧复核）。两者对同一文件判定不一致时，会出现
    「lint 说没问题、检索层解析不出来」这类**静默失效**——本库头号失效形态。

    🔴 2026-11-02：默认改为**全量**扫描（含项目卡）。旧实现随机抽 120 页，
    实测只报 1 处 `null vs "null"`，独立实现数出 21 处（13 institution +
    8 corresponding_author）——**抽样范围本身就是计数器缺陷**（历史事故记录）。
    全量（千页量级）解析约 2 s，代价可接受；`sample_n` 仍保留给临时排查用。

    判定口径（**分级**，不分级就会让噪声淹没真问题）：
      · **键集相同** —— 硬失败。键丢了才会导致整块元数据静默消失。
      · **标量值** —— 以「非转义类」分歧为硬失败。
        2026-11-02 前 `_unquote` 不反转义，102 个**合法**双引号 YAML 被读成
        `\\"`（检索摘要多出反斜杠），当时误判为写入侧数据卫生问题；现已按
        YAML 规则反转义，全库真分歧 0。`escape_div` 仅留作回归观测。
      · **列表值** —— 2026-11-02 起纳入硬失败。旧实现只查键、遇 list 直接 skip，
        而 `parse_frontmatter` 的列表正则要求 `-` 前有空白，本库的块状列表
        全部写在第 0 列 ⇒ authors/tags/aliases/gap **一直是空列表**却从未被自检发现。
        现在逐元素比较（含类型），逼着数据写对引号/别把列表写成 `1,2,3-...`。
    """
    try:
        import random
        import yaml
        files = sorted(K.iter_page_files(include_projects=True))
        if not files:
            print("  [skip] 库内无页面，跳过双解析器检查")
            return ok
        rnd = random.Random(20261014)              # 固定种子：可复现
        sample = (files if sample_n is None
                  else rnd.sample(files, min(sample_n, len(files))))
        key_mismatch, val_mismatch, list_mismatch = [], [], []
        parsed, escape_div = 0, 0
        for p in sample:
            fm_raw, _ = K.split_frontmatter(K.read_text(p))
            if not fm_raw.strip():
                continue
            try:
                y = yaml.safe_load(fm_raw)
            except Exception:                      # noqa: BLE001
                continue                           # yaml 自己都解析不了 ⇒ 交给 kb_lint 报
            if not isinstance(y, dict):
                continue
            m = K.parse_frontmatter(fm_raw)
            parsed += 1
            kd = set(y) ^ set(m)
            if kd:
                key_mismatch.append((os.path.basename(p), sorted(kd)))
            for k in set(y) & set(m):
                yv, mv = y[k], m[k]
                if isinstance(yv, list) or isinstance(mv, list):
                    # 列表形态必须两边都是 list，且逐元素相等。类型差异
                    # （YAML 把裸 `1` 读成 int、`NO` 读成 False）也算失败：
                    # 那是页面该加引号的数据问题，解析器不替它猜。
                    if (isinstance(yv, list) and isinstance(mv, list)
                            and yv == mv):
                        continue
                    list_mismatch.append(
                        (os.path.basename(p), k, str(yv)[:80], str(mv)[:80]))
                    continue
                # ⚠️ **比较必须用完整值**：曾把显示用的截断串拿去比较，
                #    结果 18 处"不一致"全是截断伪影（前 25 字相同、后面才分叉）。
                #    这正是本库「计数器本身出错却被读成内容质量」的形态。
                a, b = str(yv), str(mv)
                if K._unquote(a) == K._unquote(b):
                    continue
                if K._unquote(b).replace('\\"', '"').replace("\\\\", "\\") \
                        == K._unquote(a):
                    escape_div += 1                # 已知的 `\"` 转义差异（见 docstring）
                    continue
                val_mismatch.append((os.path.basename(p), k, a[:60], b[:60]))
        good = not key_mismatch
        print(f"  [{'ok' if good else 'FAIL'}] 双解析器键集一致"
              f"（抽 {parsed} 页，键差集非空 {len(key_mismatch)} 页）")
        for n, ks in key_mismatch[:3]:
            print(f"        - {n}: 差集 {ks}")
        ok = ok and good
        good2 = not val_mismatch
        print(f"  [{'ok' if good2 else 'FAIL'}] 双解析器标量值一致"
              f"（真分歧 {len(val_mismatch)} 处；另 {escape_div} 处为"
              f"转义类差异，仅作回归观测，不计失败）")
        for n, k, a, b in val_mismatch[:5]:
            print(f"        - {n} [{k}]: yaml={a!r} vs kb_lib={b!r}")
        ok = ok and good2
        good3 = not list_mismatch
        print(f"  [{'ok' if good3 else 'FAIL'}] 双解析器列表值一致"
              f"（真分歧 {len(list_mismatch)} 处）")
        for n, k, a, b in list_mismatch[:5]:
            print(f"        - {n} [{k}]: yaml={a!r} vs kb_lib={b!r}")
        ok = ok and good3
        if escape_div:
            print("  [info] 仍有转义类差异：先核对原始 YAML 的引号规则，"
                  "不要假定是页面数据写坏（`\\\"` 本身是合法转义）")
        # 反例夹具：含冒号值 / 行内数组 / 转义引号 / 显式 null
        #   null 项是 2026-11-02 的回归夹具：裸 `null`/`~` 必须与 PyYAML 一样读成 None，
        #   不能读成字符串 "null"（全库 21 个字段曾因此分歧）。
        probe = ('type: source\ntags: [a, b]\nsummary: "含: 冒号"\n'
                 'title: "带 \\" 引号"\ninstitution: null\n'
                 'corresponding_author: ~\n')
        m = K.parse_frontmatter(probe)
        y = yaml.safe_load(probe)
        good4 = (set(y) == set(m) and m.get("type") == "source"
                 and m.get("tags") == ["a", "b"]
                 and m.get("title") == '带 " 引号'
                 and m.get("institution") is None
                 and m.get("corresponding_author") is None
                 and y.get("institution") is None
                 and y.get("corresponding_author") is None)
        print(f"  [{'ok' if good4 else 'FAIL'}] 反例夹具：含冒号值/行内数组/"
              f"转义引号/显式 null —— 两解析器键集相同且 null 语义一致"
              f"（yaml={sorted(y)}，kb={sorted(m)}）")
        ok = ok and good4
        # 2026-11-02 回归夹具：块状列表在第 0 列、多行 plain/引号标量、
        # 行内列表中的逗号/撇号、空键 → None。
        probe2 = ('authors:\n- 甲\n- 乙\ntags: [a, "1,2,3-丙", "MM\'X"]\n'
                  'institution: 某某大学\n  Str. 43, Germany\n'
                  'summary: "第一行\n  第二行"\nempty:\nnext: v\n')
        m2 = K.parse_frontmatter(probe2)
        y2 = yaml.safe_load(probe2)
        good5 = (set(y2) == set(m2)
                 and m2.get("authors") == ["甲", "乙"]
                 and m2.get("tags") == ["a", "1,2,3-丙", "MM'X"]
                 and m2.get("institution") == "某某大学 Str. 43, Germany"
                 and m2.get("summary") == "第一行 第二行"
                 and m2.get("empty") is None
                 and all(m2.get(k) == y2.get(k) for k in
                         ("authors", "tags", "institution", "summary", "empty")))
        print(f"  [{'ok' if good5 else 'FAIL'}] 回归夹具：第 0 列块列表/"
              f"跨行标量/行内引号逗号/空键 None —— 与 PyYAML 逐值一致"
              f"（kb={m2}）")
        ok = ok and good5
        # 2026-11-04 回归夹具（诊断 #4 D5）：YAML 1.1 裸布尔。
        # 全库曾有 118 处 `skeleton: true` 分歧（PyYAML→True，kb_lib→'true'），
        # 一个根因。夹具同时钉住**正例**（裸 true/false/yes/on 必须变 bool）
        # 与**反例**（带引号的 "true" 与单个 y/n 必须仍是字符串）——
        # 只测正例会漏掉"把带引号的值也强转"这个反向错误。
        probe3 = ('skeleton: true\ndraft: false\nopt_in: yes\npower: off\n'
                  'quoted: "true"\nsingle: y\nlist: [a, true]\nitems:\n- no\n- "no"\n')
        m3 = K.parse_frontmatter(probe3)
        y3 = yaml.safe_load(probe3)
        good6 = (set(y3) == set(m3)
                 and m3.get("skeleton") is True and y3.get("skeleton") is True
                 and m3.get("draft") is False and y3.get("draft") is False
                 and m3.get("opt_in") is True and y3.get("opt_in") is True
                 and m3.get("power") is False and y3.get("power") is False
                 and m3.get("quoted") == "true" and y3.get("quoted") == "true"
                 and m3.get("single") == "y" and y3.get("single") == "y"
                 and m3.get("list") == y3.get("list") == ["a", True]
                 and m3.get("items") == y3.get("items") == [False, "no"])
        print(f"  [{'ok' if good6 else 'FAIL'}] 回归夹具：YAML 1.1 裸布尔"
              f"（true/false/yes/on/off → bool；\"true\" 与裸 y 仍是字符串；"
              f"列表逐元素同规则）"
              f"（kb={m3.get('skeleton')!r}/{m3.get('quoted')!r}/"
              f"{m3.get('items')!r}）")
        ok = ok and good6
    except ImportError:
        print("  [info] 未安装 pyyaml，跳过双解析器一致性检查")
    except Exception as _e:                                    # noqa: BLE001
        print(f"  [FAIL] 双解析器检查异常：{_e}")
        ok = False
    return ok


def check_page_fm_sidecar(ok):
    """🆕 2026-10-15：`page_fm` 侧车与向后兼容的守门夹具。

    背景：首轮把预取限定词内嵌进 `meta.json`，使它 961 KB → 1214 KB（+26%）。
    第二轮拆成 `meta_fm.json` 侧车。本夹具钉住三条契约：

      ① 侧车存在 ⇒ `load_page_fm` 读侧车
      ② 侧车缺失但 `meta` 内嵌 `page_fm`（**旧索引过渡态**）⇒ 回退到内嵌，**不静默给空**
         ——静默空值比慢更危险：L2 的立身之本就是随身带可靠性限定词
      ③ 两者都没有 ⇒ 返回空 dict 且**不抛异常**（不能让检索整体失败）

    ⚠️ 用一个合成 meta 测②③，**不碰真实索引文件**（自检零副作用）。
    """
    import json as _json
    try:
        # ① 真实侧车（存在时必须读得到）
        real = K.load_page_fm()
        print(f"  [{'ok' if real else 'info'}] 侧车 meta_fm.json 可用（{len(real)} 条）")
        # ② 旧索引过渡态：合成 meta 带内嵌 page_fm，且**临时把侧车路径指向不存在的位置**
        saved = K.META_FM_PATH
        try:
            K.META_FM_PATH = os.path.join(K.INDEX_DIR, "__nonexistent_for_selftest__.json")
            synth = {"page_fm": {"某页": {"source_reliability": "R"}}}
            got = K.load_page_fm(synth)
            good = got.get("某页", {}).get("source_reliability") == "R"
            print(f"  [{'ok' if good else 'FAIL'}] 侧车缺失时回退 meta 内嵌 page_fm"
                  f"（拿到 {len(got)} 条）")
            ok = ok and good
            # ③ 两者都无 ⇒ 空 dict 且不抛
            got2 = K.load_page_fm({})
            good2 = got2 == {}
            print(f"  [{'ok' if good2 else 'FAIL'}] 侧车与内嵌都无 ⇒ 空 dict 不抛异常")
            ok = ok and good2
            # ④ 反例：侧车内容坏掉时必须回退，而不是让检索崩
            bad_path = os.path.join(K.INDEX_DIR, "__bad_for_selftest__.json")
            with open(bad_path, "w", encoding="utf-8") as f:
                f.write("{ this is not json")
            K.META_FM_PATH = bad_path
            try:
                got3 = K.load_page_fm({"page_fm": {"p": {"si_status": "missing"}}})
                good3 = got3.get("p", {}).get("si_status") == "missing"
                print(f"  [{'ok' if good3 else 'FAIL'}] 反例：侧车 JSON 损坏 ⇒ 回退内嵌不崩")
                ok = ok and good3
            finally:
                try:
                    os.remove(bad_path)
                except OSError:
                    pass
        finally:
            K.META_FM_PATH = saved
    except Exception as _e:                                    # noqa: BLE001
        print(f"  [FAIL] page_fm 侧车检查异常：{_e}")
        ok = False
    return ok


def check_temp_dir_helper(ok):
    """🆕 2026-10-15：临时目录助手的守门夹具（正例 + 反例 + 回退）。

    为什么值得一个夹具：`K.make_temp_dir` / `K.temp_dir` 现在是**全部工具 selftest 的
    共同底座**（此前 12 个工具各写一份手写回退，且在受限环境下全线崩在"建目录"这一步）。
    底座一坏，几十个工具的自检会**同时**变成假失败 —— 正是「计数器本身出错却被读成
    内容质量问题」那一类失效，必须钉住。
    """
    try:
        d = K.make_temp_dir(prefix="kb_selftest_t_")
        wrote = False
        try:
            p = os.path.join(d, "x.txt")
            with open(p, "w", encoding="utf-8") as f:
                f.write("hello")
            with open(p, encoding="utf-8") as f:
                wrote = f.read() == "hello"
        finally:
            K.remove_temp_dir(d)
        print(f"  [{'ok' if wrote else 'FAIL'}] make_temp_dir 建出的目录**确实可写**"
              f"（写了能读回）")
        ok = ok and wrote

        cleaned = not os.path.exists(d)
        print(f"  [{'ok' if cleaned else 'FAIL'}] remove_temp_dir 真删掉了")
        ok = ok and cleaned

        # `with` 形态
        with K.temp_dir(prefix="kb_selftest_ctx_") as cd:
            inside = os.path.isdir(cd)
        print(f"  [{'ok' if inside and not os.path.exists(cd) else 'FAIL'}] "
              f"temp_dir() 上下文可用且退出后清理")
        ok = ok and inside and not os.path.exists(cd)

        # 回退：第一个基目录不可写 ⇒ 必须落到第二个可用基目录
        import glob as _glob
        g1 = os.path.join(K.VAULT, ".qc", "_selftest_nonexistent_base_zzz")
        import tempfile as _tf
        d2 = K.make_temp_dir(prefix="kb_selftest_fb_", bases=[g1, _tf.gettempdir()])
        good_fb = bool(d2) and os.path.isdir(d2)
        K.remove_temp_dir(d2)
        print(f"  [{'ok' if good_fb else 'FAIL'}] 反例：首个基目录不可用 ⇒ 回退到下一个可写基目录")
        ok = ok and good_fb

        # 反例：全部基目录都不可用 ⇒ 必须抛 OSError（不能静默返回坏目录）
        try:
            K.make_temp_dir(bases=[os.path.join("Z:", "nope_zzz"),
                                   os.path.join("Z:", "nope_yyy")])
            raised = False
        except OSError:
            raised = True
        print(f"  [{'ok' if raised else 'FAIL'}] 反例：无可用基目录 ⇒ 抛 OSError（不静默返坏路径）")
        ok = ok and raised
    except Exception as _e:                                    # noqa: BLE001
        print(f"  [FAIL] 临时目录助手检查异常：{_e}")
        ok = False
    return ok


def check_kb_root(ok):
    """🆕 2026-10-31：知识库根可插拔（`MATSCI_KB_ROOT`）的守门夹具。

    为什么值得夹具：导出包与 MCP 插件都靠它接「他人的知识库」。
    这里最危险的失效不是"读不到"，而是**静默回退到本仓库**——
    用户以为在看 A 库、实际在看 B 库，而产出的每条推荐都还长得像有证据。
    所以反例的判据是「必须抛错」，不是「能跑」。
    """
    env_key = K.KB_ROOT_ENV
    saved = os.environ.get(env_key)

    def _with_env(val):
        if val is None:
            os.environ.pop(env_key, None)
        else:
            os.environ[env_key] = val

    try:
        default_root = os.path.dirname(os.path.dirname(os.path.abspath(K.__file__)))

        # 正例 1：不设变量 ⇒ 与旧行为逐字符相同
        _with_env(None)
        got = K._resolve_vault()
        same = os.path.normcase(got) == os.path.normcase(default_root)
        print(f"  [{'ok' if same else 'FAIL'}] KB_ROOT 未设 ⇒ 根仍为 dirname(dirname(__file__))"
              f"（旧行为不变）")
        ok = ok and same

        # 正例 2：空串/纯空格 ⇒ 视为未设。
        # 🔴 判据不能只看 `_resolve_vault()`：`abspath("")` 恰好等于**当前工作目录**，
        #    而自检通常就在库根跑 ⇒ 两种实现给出同一个答案，夹具分不出来
        #    （第一版这么写，注入 K3 时没红）。
        #    两处同时加固：① 来源标记必须说 default；② **换一个工作目录**再测——
        #    这样「把空串当真」的实现会返回那个别的目录，而不是库根。
        for blank in ("", "   "):
            _with_env(blank)
            cwd0 = os.getcwd()
            with K.temp_dir(prefix="kb_root_cwd_") as other:
                os.chdir(os.path.abspath(other))
                try:
                    live = K._resolve_vault()
                except Exception:
                    live = None
                finally:
                    os.chdir(cwd0)
            try:
                _, how = K.describe_kb_root()
            except Exception:
                how = "raised"
            good = (live is not None
                    and os.path.normcase(live) == os.path.normcase(default_root)
                    and how.startswith("default:"))
            print(f"  [{'ok' if good else 'FAIL'}] KB_ROOT={blank!r} ⇒ 视为未设，走默认"
                  f"（来源={how}；换工作目录后仍返回库根={good}）")
            ok = ok and good

        # 正例 3：指向一个**与默认不同**的真实库根 ⇒ 必须采用它。
        # 🔴 必须不同：第一版把 env 指成本仓库，于是「采纳」与「静默回退」结果相同，
        #    注入「完全忽略环境变量」（K6）时夹具全绿 ⇒ 装饰性夹具。
        with K.temp_dir(prefix="kb_root_alt_") as alt:
            alt_abs = os.path.abspath(alt)
            os.makedirs(os.path.join(alt_abs, "tools"), exist_ok=True)
            differs = os.path.normcase(alt_abs) != os.path.normcase(default_root)
            _with_env(alt_abs)
            try:
                adopted_root = K._resolve_vault() if differs else None
            except Exception:
                adopted_root = None
            adopted = bool(adopted_root) and \
                os.path.normcase(adopted_root) == os.path.normcase(alt_abs)
            print(f"  [{'ok' if adopted else 'FAIL'}] KB_ROOT 指向与默认不同的库根 ⇒ 采用该根"
                  f"（期望 {os.path.basename(alt_abs)}，实际 "
                  f"{os.path.basename(adopted_root or '(未采纳)')}）")
            ok = ok and adopted

            # 派生路径必须**跟着这个根走**（纯函数，直接喂另一个根）
            dp = K.derived_paths(alt_abs)
            follow = (dp["WIKI"] == os.path.join(alt_abs, "wiki")
                      and dp["INDEX_DIR"] == os.path.join(alt_abs, "wiki", ".index")
                      and dp["META_PATH"].endswith(os.path.join(".index", "meta.json")))
            print(f"  [{'ok' if follow else 'FAIL'}] derived_paths(该根) ⇒ "
                  f"WIKI/INDEX_DIR/META_PATH 全部跟着新根走")
            ok = ok and follow

        # 正例 4：模块级常量本身也必须落在当前根下（防「只改函数忘了常量」）
        derived_ok = (K.WIKI.startswith(K.VAULT) and K.INDEX_DIR.startswith(K.WIKI)
                      and K.META_PATH.startswith(K.INDEX_DIR))
        print(f"  [{'ok' if derived_ok else 'FAIL'}] 模块级 WIKI/INDEX_DIR/META_PATH 以 VAULT 为前缀")
        ok = ok and derived_ok

        # 反例 1：路径不存在 ⇒ 必须抛错，绝不静默回退
        _with_env(os.path.join("Z:", "definitely_not_here_zzz"))
        try:
            K._resolve_vault()
            raised = False
        except RuntimeError:
            raised = True
        print(f"  [{'ok' if raised else 'FAIL'}] 反例：KB_ROOT 指向不存在的目录 ⇒ 抛 RuntimeError"
              f"（不静默回退到本仓库）")
        ok = ok and raised

        # 反例 2：目录存在但不是知识库根（无 tools/）⇒ 也必须抛错
        with K.temp_dir(prefix="kb_root_bad_") as bad:
            _with_env(bad)
            try:
                K._resolve_vault()
                raised2 = False
            except RuntimeError:
                raised2 = True
        print(f"  [{'ok' if raised2 else 'FAIL'}] 反例：目录存在但缺 tools/ ⇒ 抛 RuntimeError")
        ok = ok and raised2

        # 正例 5：describe_kb_root 能说出**根从哪来**（排障时最要紧的一句）
        with K.temp_dir(prefix="kb_root_desc_") as alt2:
            alt2_abs = os.path.abspath(alt2)
            os.makedirs(os.path.join(alt2_abs, "tools"), exist_ok=True)
            _with_env(alt2_abs)
            try:
                _, how = K.describe_kb_root()
            except Exception:
                how = "raised"
            said_env = how.startswith("env:")
        _with_env(None)
        _, how2 = K.describe_kb_root()
        said_default = how2.startswith("default:")
        good = said_env and said_default
        print(f"  [{'ok' if good else 'FAIL'}] describe_kb_root() 区分 env 与 default 来源"
              f"（{how} / {how2}）")
        ok = ok and good
    except Exception as _e:                                    # noqa: BLE001
        print(f"  [FAIL] 知识库根检查异常：{_e}")
        ok = False
    finally:
        _with_env(saved)
    return ok


def check_skill_dual_entry(ok):
    """E6 底座夹具（2026-11-14）：项目技能双入口完整性。

    `.dsh/skills`（真源）每个技能都应在 `.claude/skills` 有可解析的 junction 对应；
    缺对应 = 某个运行时静默看不到该技能（「已声明≠已生效」的结构性一半，可机检）。
    全部用普通目录 + 合成 `dir /al` 文本，**不需造真 junction**（便携、零副作用）。
    """
    # 1) 纯解析器：喂合成 `cmd /c dir /al` 输出，验证只认 <JUNCTION> 行
    sample = (
        "2026-10-08  22:35    <JUNCTION>     kb-query [Z:\\KB\\.dsh\\skills\\kb-query]\n"
        "2026-10-11  22:11    <DIR>          not-a-junction\n"
        "2026-10-18  22:00    <JUNCTION>     sci-assistant [\\??\\Global\\Z:\\KB\\.dsh\\skills\\sci-assistant]\n"
    )
    parsed = K._parse_dir_al(sample)
    good_parse = (parsed.get("kb-query") == "Z:\\KB\\.dsh\\skills\\kb-query"
                  and "not-a-junction" not in parsed
                  and parsed.get("sci-assistant", "").endswith("sci-assistant"))
    print(f"  [{'ok' if good_parse else 'FAIL'}] _parse_dir_al 解析 <JUNCTION> 行、忽略 <DIR> 行")
    ok = ok and good_parse

    # 2) skill_dual_entry：临时库，普通目录即可（无真 junction）
    with K.temp_dir(prefix="kb_selftest_skill_") as v:
        os.makedirs(os.path.join(v, ".dsh", "skills", "foo"))     # foo 真源在、.claude 侧缺
        os.makedirs(os.path.join(v, ".dsh", "skills", "bar"))
        os.makedirs(os.path.join(v, ".claude", "skills", "bar"))  # bar 两侧都有
        res = K.skill_dual_entry(v)
        good_missing = (sorted(res["names"]) == ["bar", "foo"]
                        and res["missing"] == ["foo"] and res["broken"] == [])
        print(f"  [{'ok' if good_missing else 'FAIL'}] skill_dual_entry 检出 .claude 侧缺失入口（foo）")
        ok = ok and good_missing
        # broken 用注入的 junction 表（目标不存在）——避免在夹具里造真 junction
        res2 = K.skill_dual_entry(v, _jt={"bar": os.path.join(v, "no-such-target")})
        good_broken = (res2["broken"] == ["bar"] and res2["missing"] == ["foo"])
        print(f"  [{'ok' if good_broken else 'FAIL'}] skill_dual_entry 检出断链 junction（注入目标不存在）")
        ok = ok and good_broken
    return ok


def main():
    ok = True

    # ---- 0. 知识库根可插拔（2026-10-31）----
    ok = check_kb_root(ok)

    # ---- 1. join_frontmatter ↔ split_frontmatter 往返（最高代价失效的守门）----
    fm = 'summary: "含冒号：的摘要"\ntags: [a, b]\n'
    body = "# 标题\n正文首行\n"
    txt = K.join_frontmatter(fm, body)
    got_fm, got_body = K.split_frontmatter(txt)
    parsed_ok = False
    try:
        import yaml
        parsed_ok = isinstance(yaml.safe_load(got_fm), dict)
    except Exception:
        parsed_ok = False
    good = (got_fm != "" and parsed_ok and got_body.startswith("# 标题"))
    print(f"  [{'ok' if good else 'FAIL'}] join→split 往返可读出 frontmatter")
    ok = ok and good

    # 🔴 夹具：开围栏 `---` 后必须有换行（旧 qc_fix_yaml 的坏形态）
    bad = "---summary: \"x\"\n---\n# t\n"
    got_fm_bad, _ = K.split_frontmatter(bad)
    bad_detected = got_fm_bad == ""
    print(f"  [{'ok' if bad_detected else 'FAIL'}] 🔴 夹具：`---summary:` 形态解析不出"
          f"（join_frontmatter 正是为消除它而生）")
    ok = ok and bad_detected

    # 🔴 夹具：闭合 `---` 后必须有换行（124 页事故形态）
    bad2 = "---\nsummary: \"x\"\n---# t\n"
    got_fm_bad2, _ = K.split_frontmatter(bad2)
    print(f"  [info] `---# t` 闭合形态 -> frontmatter="
          f"{'解析出' if got_fm_bad2 else '解析不出'}"
          f"（注：_FM_RE 允许 `---` 后行尾，主要防线是 join_frontmatter）")

    # 正例：join_frontmatter 必须产出规范的换行布局
    good_layout = txt.startswith("---\n") and "\n---\n" in txt
    print(f"  [{'ok' if good_layout else 'FAIL'}] 规范布局：`---\\n` 开头、`\\n---\\n` 闭合")
    ok = ok and good_layout

    # ---- 2. QC 工作目录解析 ----
    # 🔴 本脚本自称"底座自检"，就不该**产生副作用**：旧版调 `qc_work_dir(create=True)`
    #    会在库里建出 `.qc/`（一次"只读自检"把目录建了出来，且 kb_toolcheck 的
    #    写盘防呆并不监视 `.qc/` ⇒ 完全隐形）。改为**只解析不创建**，
    #    并用 `MATSCI_QC_DIR` 环境变量把解析规则本身测掉（kb_lib 支持该覆盖）。
    wd = K.qc_work_dir()
    inside_vault = os.path.abspath(wd).startswith(os.path.abspath(K.VAULT))
    not_archive = "_archive" not in wd.replace("/", "\\")
    print(f"  [{'ok' if inside_vault else 'FAIL'}] qc_work_dir 在库内 -> {wd}")
    ok = ok and inside_vault
    print(f"  [{'ok' if not_archive else 'FAIL'}] 默认写盘目标不在 _archive（归档只进不出）")
    ok = ok and not_archive
    # 临时目录统一走 K.temp_dir()（可写 + 清理不抛），理由见文件头说明。
    with K.temp_dir(prefix="kb_selftest_") as _qd:
        _old = os.environ.get("MATSCI_QC_DIR")
        try:
            os.environ["MATSCI_QC_DIR"] = _qd
            override_ok = os.path.abspath(K.qc_work_dir(create=True)) == os.path.abspath(_qd)
            created_here = os.path.isdir(_qd)
        finally:
            if _old is None:
                os.environ.pop("MATSCI_QC_DIR", None)
            else:
                os.environ["MATSCI_QC_DIR"] = _old
        print(f"  [{'ok' if override_ok and created_here else 'FAIL'}] "
              f"MATSCI_QC_DIR 覆盖生效且 create=True 落在覆盖目录（自检零副作用）")
        ok = ok and override_ok and created_here
    # qc_input 的契约是「**解析规则**」（优先新工作目录、回退归档），不是
    #   「某个具体真源文件在不在」——后者是库专属前提，全新空库（无 .qc/queue.json）
    #   会因此假 FAIL。旧版正例写成 `os.path.exists(qc_input("queue.json"))`，
    #   把「解析规则对」错判成「库里有 queue.json」，属于把缺省值当断言。
    #   改为：在隔离临时目录里钉住**行为**——存在则返回该路径、缺失则不误报。
    with K.temp_dir(prefix="kb_selftest_qc_") as _qid:
        _oldq = os.environ.get("MATSCI_QC_DIR")
        try:
            os.environ["MATSCI_QC_DIR"] = _qid
            made = os.path.join(_qid, "queue.json")
            open(made, "w", encoding="utf-8").write("{}")
            ok_hit = os.path.abspath(K.qc_input("queue.json")) == os.path.abspath(made)
            miss = K.qc_input("绝不存在的-xyz.json")
            ok_miss = not os.path.exists(miss)
        finally:
            if _oldq is None:
                os.environ.pop("MATSCI_QC_DIR", None)
            else:
                os.environ["MATSCI_QC_DIR"] = _oldq
    print(f"  [{'ok' if ok_hit else 'FAIL'}] qc_input 正例：已存在文件解析到工作目录")
    print(f"  [{'ok' if ok_miss else 'FAIL'}] qc_input 反例：不存在文件不误报")
    ok = ok and ok_hit and ok_miss

    # ---- 3. read_text：CRLF/LF 混合（本库已知陷阱）----
    with tempfile.NamedTemporaryFile(delete=False, suffix=".md") as fh:
        fh.write(b"---\r\ntype: source\r\n---\r\nbody\r\n")
        crlf = fh.name
    with tempfile.NamedTemporaryFile(delete=False, suffix=".md") as fh:
        fh.write(b"---\ntype: source\n---\nbody\n")
        lf = fh.name
    a = K.read_text(crlf)
    b = K.read_text(lf)
    same = a == b and "\r" not in a
    print(f"  [{'ok' if same else 'FAIL'}] read_text 归一化换行（CRLF 与 LF 同结果）")
    ok = ok and same
    fm_crlf, body_crlf = K.split_frontmatter(a)
    good = fm_crlf != "" and "type: source" in fm_crlf and body_crlf.strip() == "body"
    print(f"  [{'ok' if good else 'FAIL'}] CRLF 文件的 frontmatter 不丢（本库静默失效陷阱）")
    ok = ok and good
    os.unlink(crlf)
    os.unlink(lf)

    # ---- 4. extract_outlinks：代码块内的 [[...]] 必须剔除 ----
    text = ("正文 [[concepts/固态电解质]]\n"
            "```\n[[concepts/示例文本]]\n```\n"
            "行内 `[[concepts/行内示例]]`\n")
    outs = K.extract_outlinks(text)
    real = [x for x in outs if "固态电解质" in x]
    fake = [x for x in outs if "示例" in x]
    good = len(real) == 1 and len(fake) == 0
    print(f"  [{'ok' if good else 'FAIL'}] extract_outlinks 剔除代码块示例 "
          f"(真={len(real)} 假={len(fake)})")
    ok = ok and good

    # ---- 4b. parse_budget / parse_layers：单一实现的行为必须与三份旧拷贝逐一等价 ----
    #      收敛动机：这三份拷贝分别在 kb.py / kb_route.py / kb_serve.py 里，
    #      同源代码必然漂移。夹具把**旧实现**写死在这里做反算，一旦新实现改变语义立刻 FAIL。
    def _old_budget(s):
        if not s:
            return None
        parts = [int(x) for x in s.split(",") if x.strip()]
        return {f"L{i + 1}": v for i, v in enumerate(parts[:3])}

    def _old_layers(s):
        return (tuple(int(x) for x in s.split(",") if x.strip()) if s
                else (1, 2, 3))

    _pcases = ["", "5,5,8", "3", "1,2,3,4,5", "10,20", " 4 , 5 ", None]
    _bdiff = [c for c in _pcases if _old_budget(c) != K.parse_budget(c)]
    _ldiff = [c for c in _pcases if _old_layers(c) != K.parse_layers(c)]
    good = not _bdiff and not _ldiff
    print(f"  [{'ok' if good else 'FAIL'}] parse_budget/parse_layers 与旧拷贝逐一等价"
          f"（预算差异 {len(_bdiff)}、分层差异 {len(_ldiff)}）")
    ok = ok and good
    # 反例：必须真的会区分，不能是"两边都返回同一种错值"的恒真夹具
    _rev = (K.parse_budget("") is None and K.parse_budget("5,5,8") == {"L1": 5, "L2": 5, "L3": 8}
            and K.parse_layers("1,2") == (1, 2) and K.parse_layers(None) == (1, 2, 3)
            and K.parse_budget("1,2,3,4") == {"L1": 1, "L2": 2, "L3": 3})
    print(f"  [{'ok' if _rev else 'FAIL'}] 反例：解析结果的具体取值正确（非恒真夹具）")
    ok = ok and _rev

    # ---- 4c. 写盘三件套（backup_file / write_text_verified / detect_eol）----
    #      这三条是 CLAUDE.md §五「写盘铁律」的**唯一实现**，`lit_finish`、
    #      `kb_lint --deep --fix --apply` 与 `qc_*` 写盘工具都调它。
    #      最关键的两点是**备份必须保留相对结构**（否则同名页互相覆盖 = 没有备份）
    #      与**写后复算**（原先 kb_lint 的 docstring 声称做了、代码里没有）。
    import shutil as _sh
    import tempfile as _tf
    _wdir = None
    try:
        _wdir = K.make_temp_dir(prefix="kb_selftest_write_")
        _saved_vault = K.VAULT
        _saved_qcw = K.qc_work_dir
        K.VAULT = _wdir
        K.qc_work_dir = lambda create=False: os.path.join(_wdir, ".qc")
        os.makedirs(os.path.join(_wdir, "wiki", "sources"), exist_ok=True)
        os.makedirs(os.path.join(_wdir, "wiki", "concepts"), exist_ok=True)
        _a = os.path.join(_wdir, "wiki", "sources", "同名.md")
        _b = os.path.join(_wdir, "wiki", "concepts", "同名.md")
        for _p, _t in ((_a, "source"), (_b, "concept")):
            with open(_p, "w", encoding="utf-8") as _f:
                _f.write(f"---\ntype: {_t}\n---\ntext-{_t}\n")
        _ba, _bb = K.backup_file(_a), K.backup_file(_b)
        good = bool(_ba and _bb and _ba != _bb
                    and open(_ba, encoding="utf-8").read().endswith("text-source\n")
                    and open(_bb, encoding="utf-8").read().endswith("text-concept\n"))
        print(f"  [{'ok' if good else 'FAIL'}] backup_file 保留相对结构（同名页不互相覆盖）")
        ok = ok and good

        _ok1, _d1 = K.write_text_verified(_a, "---\ntype: source\n---\nnew\n")
        _ok2, _d2 = K.write_text_verified(_a, "no frontmatter\n")
        good = _ok1 and (not _ok2) and "frontmatter" in _d2
        print(f"  [{'ok' if good else 'FAIL'}] write_text_verified 正例通过 / 反例"
              f"（写坏 frontmatter）被拦（{_d2[:34]}）")
        ok = ok and good
        # 换行：CRLF 必须写回 CRLF；平局取 LF
        _c = os.path.join(_wdir, "wiki", "concepts", "crlf.md")
        with open(_c, "wb") as _f:
            _f.write(b"---\r\ntype: concept\r\n---\r\nbody\r\n")
        K.write_text_keep_eol(_c, "---\ntype: concept\n---\nnew\n")
        _raw = open(_c, "rb").read()
        good = _raw.count(b"\r\n") == 4 and _raw.count(b"\n") == 4
        print(f"  [{'ok' if good else 'FAIL'}] write_text_keep_eol 保住 CRLF"
              f"（crlf={_raw.count(b'\r\n')} bare={_raw.count(b'\n') - _raw.count(b'\r\n')}）")
        ok = ok and good
        _tie = os.path.join(_wdir, "wiki", "concepts", "tie.md")
        with open(_tie, "wb") as _f:
            _f.write(b"a\r\nb\r\nc\nd\n")
        _e, _m = K.detect_eol(_tie)
        good = (_m is True) and (_e == "\n")
        print(f"  [{'ok' if good else 'FAIL'}] detect_eol 识别混合且平局取 LF（{_e!r} mixed={_m}）")
        ok = ok and good
    finally:
        if _wdir:
            try:
                K.VAULT = _saved_vault
                K.qc_work_dir = _saved_qcw
            except NameError:
                pass
            _sh.rmtree(_wdir, ignore_errors=True)

    # ---- 5. 页面集合与索引一致（同源口径）----
    # ⚠️ 这一项依赖**派生数据**（wiki/.index/meta_full.json），索引没重建就会不对称。
    #    它此前计入 `ok` ⇒ 底座自检会因为"索引还没刷新"而 FAIL，而那不是代码缺陷
    #    （CLAUDE.md §六「校验器纪律」 明确点名这类"自检断言当前状态"的腐坏）。
    #    ⇒ 降为 WARN：报出来，但不否定整轮自检。
    names = set()
    # 🔴 索引口径包含项目卡（kb_build_index.scan_pages 用 include_projects=True）；
    #    这里若只数 wiki 页，项目卡会被误报成「索引多出来的幽灵页」。
    for rel in K.iter_page_files(include_projects=True):
        names.add(os.path.basename(rel)[:-3])
    full = os.path.join(K.INDEX_DIR, "meta_full.json")
    if os.path.exists(full):
        import json
        with open(full, encoding="utf-8") as fh:
            mp = set(json.load(fh).get("pages", {}).keys())
        diff = len(names ^ mp)
        print(f"  [{'ok' if diff == 0 else 'WARN'}] 页面集合 vs 索引 对称差={diff}"
              f"（页 {len(names)} / 索引 {len(mp)}）"
              + ("" if diff == 0 else "  ← 跑 kb_build_index.py 刷新，非代码缺陷"))
    else:
        print("  [info] meta_full.json 不存在，跳过索引一致性检查")

    ok = check_type_dir(ok) and ok
    ok = check_dual_parser(ok) and ok
    ok = check_page_fm_sidecar(ok) and ok
    ok = check_temp_dir_helper(ok) and ok
    ok = check_skill_dual_entry(ok) and ok

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


if __name__ == "__main__":
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__ or "用法: python tools/kb_selftest.py   # 运行 kb_lib 底座自检")
        print("\n用法: python tools/kb_selftest.py   # 无参数即运行全部底座自检")
        print("      python tools/kb_selftest.py --dual-parser  # 只跑全库双解析器等价性")
        sys.exit(0)
    # 🆕 2026-11-02：把「全库双解析器等价性」做成独立入口。改完 frontmatter 写入/解析
    # 代码后，不必等整套自检（也避免被无关项干扰），单独一条命令就能得到 0/1 判据。
    if "--dual-parser" in sys.argv:
        ok = True
        ok = check_dual_parser(ok) and ok
        print("=== dual-parser", "PASS ===" if ok else "FAIL ===")
        sys.exit(0 if ok else 1)
    sys.exit(main())
